"""matplotlib.backends.backend_qtcairo — qtcairo backend stub.

The shim renders every figure through plotly, so this module exists to
satisfy ``from matplotlib.backends.backend_qtcairo import
FigureCanvasQTCairo`` imports. Saving uses plotly's native export.
"""

from matplotlib.backends._backend_helpers import (
    _make_canvas, _make_manager, _make_backend,
)


FigureCanvasQTCairo = _make_canvas('FigureCanvasQTCairo', 'png')
FigureManagerQTCairo = _make_manager('FigureManagerQTCairo')

# Aliases — every backend exposes ``FigureCanvas`` and ``FigureManager``.
FigureCanvas = FigureCanvasQTCairo
FigureManager = FigureManagerQTCairo

# Backend class registered with matplotlib's _Backend system.
_BackendStub = _make_backend('_BackendQTCairo', FigureCanvas, FigureManager)
new_figure_manager = _BackendStub.new_figure_manager
draw_if_interactive = _BackendStub.draw_if_interactive
show = _BackendStub.show
